/**
 * TASK: Complete the Robot class below.
 *
 * The Describable interface (provided above, do not change it) declares:
 *   - String kind();                          (abstract)
 *   - default String describe() -> "a " + kind()
 *   - default String shout()    -> describe().toUpperCase() + "!"
 *
 * Robot must:
 *   - implement kind() to return "robot"
 *   - OVERRIDE the default describe() to return "unit of kind robot"
 *     (build it as "unit of kind " + kind())
 *
 * Because shout() calls describe(), shout() must then return
 * "UNIT OF KIND ROBOT!" without you touching shout() at all.
 */
interface Describable {
    String kind();

    default String describe() {
        return "a " + kind();
    }

    default String shout() {
        return describe().toUpperCase() + "!";
    }
}

public class Robot implements Describable {

    @Override
    public String kind() {
        // TODO: return "robot"
        return "";
    }

    @Override
    public String describe() {
        // TODO: return "unit of kind " + kind()
        return "";
    }
}

