public class RobotTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Robot r = new Robot();
        check("kind()", "robot", r.kind());
        check("describe() is overridden", "unit of kind robot", r.describe());
        check("shout() uses the override", "UNIT OF KIND ROBOT!", r.shout());

        Describable d = new Robot();
        check("describe() through interface reference", "unit of kind robot", d.describe());
        check("shout() through interface reference", "UNIT OF KIND ROBOT!", d.shout());

        Describable plain = () -> "toaster";
        check("default describe() still works for other implementors", "a toaster", plain.describe());
        check("default shout() still works for other implementors", "A TOASTER!", plain.shout());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

